/*\n  # Fix Proposal Labor Phases RLS for Consistency\n\n  ## Summary\n  Update proposal_line_item_labor_phases to be consistent with the proposals table\n  visibility scope. If a user can view a proposal, they should be able to view and\n  manage the labor phases for its line items.\n\n  ## Changes Made\n\n  1. **proposal_line_item_labor_phases**\n     - SELECT: Can view if user can view the parent proposal (via line_items)\n     - INSERT: Can create if user can view the parent proposal\n     - UPDATE: Can update if user can view the parent proposal\n     - DELETE: Can delete if user can view the parent proposal\n\n  ## Security Notes\n  - Maintains consistent access control across all proposal-related tables\n  - Uses the proposal visibility scope system through line items\n*/\n\n-- Drop existing policies\nDROP POLICY IF EXISTS "Authenticated users can view line item labor phases" ON proposal_line_item_labor_phases

\nDROP POLICY IF EXISTS "Authenticated users can manage line item labor phases" ON proposal_line_item_labor_phases

\n\n-- Create new consistent policies\nCREATE POLICY "Users can view line item labor phases"\n  ON proposal_line_item_labor_phases\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 \n      FROM proposal_line_items pli\n      JOIN proposals p ON p.id = pli.proposal_id\n      WHERE pli.id = proposal_line_item_labor_phases.line_item_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can insert line item labor phases"\n  ON proposal_line_item_labor_phases\n  FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 \n      FROM proposal_line_items pli\n      JOIN proposals p ON p.id = pli.proposal_id\n      WHERE pli.id = proposal_line_item_labor_phases.line_item_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can update line item labor phases"\n  ON proposal_line_item_labor_phases\n  FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 \n      FROM proposal_line_items pli\n      JOIN proposals p ON p.id = pli.proposal_id\n      WHERE pli.id = proposal_line_item_labor_phases.line_item_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can delete line item labor phases"\n  ON proposal_line_item_labor_phases\n  FOR DELETE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 \n      FROM proposal_line_items pli\n      JOIN proposals p ON p.id = pli.proposal_id\n      WHERE pli.id = proposal_line_item_labor_phases.line_item_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n
